"""nav_demo.launch.pyLaunches TurtleBot3 in a selected Gazebo world, brings upturtlebot3_navigation2 (AMCL + planners + controllers) against apreviously-saved map, and starts navigation.Arguments:    world:        Full path to the Gazebo world.        Defaults to:        #world:=/root/turtlebot3_ws/install/my_robot_bringup/share/my_robot_bringup/worlds/warehouse_world.sdf        mao:        Full path to the map.        Defaults to:        #map:=/root/turtlebot3_ws/src/custom_packages/my_robot_bringup/maps/warehouse_map.yaml        x_pose:        Initial X position of the robot.        Defaults to 0.0.    y_pose:        Initial Y position of the robot.        Defaults to 0.0.Usage:    # Use all defaults:    ros2 launch my_robot_bringup nav_demo.launch.py       #default arguments         #world:=/root/turtlebot3_ws/install/my_robot_bringup/share/my_robot_bringup/worlds/warehouse_world.sdf	 #map:=/root/turtlebot3_ws/src/custom_packages/my_robot_bringup/maps/warehouse_map.yaml                #x_pose:=0.0            #y_pose:=0.0            # Specify everything example:    ros2 launch my_robot_bringup nav_demo.launch.py \        world:=/root/turtlebot3_ws/src/turtlebot3_simulations/turtlebot3_gazebo/worlds/turtlebot3_world.world \        map:=/root/turtlebot3_ws/src/custom_packages/my_robot_bringup/maps/tb3world_map.yaml \        x_pose:=-2.0 \        y_pose:=-0.5"""import osfrom ament_index_python.packages import get_package_share_directoryfrom launch import LaunchDescriptionfrom launch.actions import DeclareLaunchArgument, IncludeLaunchDescriptionfrom launch.launch_description_sources import PythonLaunchDescriptionSourcefrom launch.substitutions import LaunchConfigurationdef generate_launch_description():    bringup_dir = get_package_share_directory('my_robot_bringup')    tb3_nav_dir = get_package_share_directory('turtlebot3_navigation2')    # ---------------------------------------------------------    # Default paths    # ---------------------------------------------------------    default_world = os.path.join(        bringup_dir,        'worlds',        'warehouse_world.sdf'    )    default_map = os.path.join(        bringup_dir,        'maps',        'warehouse_map.yaml'    )    # ---------------------------------------------------------    # Launch arguments    # ---------------------------------------------------------    world_arg = DeclareLaunchArgument(        'world',        default_value=default_world,        description='Full path to the Gazebo world file'    )    map_arg = DeclareLaunchArgument(        'map',        default_value=default_map,        description='Full path to the saved map YAML file'    )    x_pose_arg = DeclareLaunchArgument(        'x_pose',        default_value='0.0',        description='Initial X position of the robot'    )    y_pose_arg = DeclareLaunchArgument(        'y_pose',        default_value='0.0',        description='Initial Y position of the robot'    )    # Resolve launch configurations    world = LaunchConfiguration('world')    map_file = LaunchConfiguration('map')    x_pose = LaunchConfiguration('x_pose')    y_pose = LaunchConfiguration('y_pose')    # ---------------------------------------------------------    # Gazebo    # ---------------------------------------------------------    world_launch = IncludeLaunchDescription(        PythonLaunchDescriptionSource(            os.path.join(                bringup_dir,                'launch',                'custom_world_demo.launch.py'            )        ),        launch_arguments={            'world': world,            'x_pose': x_pose,            'y_pose': y_pose,        }.items(),    )    # ---------------------------------------------------------    # TurtleBot3 Navigation2 parameters    # ---------------------------------------------------------    turtlebot3_model = os.environ['TURTLEBOT3_MODEL']    ros_distro = os.environ.get('ROS_DISTRO')    param_file_name = turtlebot3_model + '.yaml'    if ros_distro == 'humble':        params_file = os.path.join(            tb3_nav_dir,            'param',            ros_distro,            param_file_name        )    else:        params_file = os.path.join(            tb3_nav_dir,            'param',            param_file_name        )    # ---------------------------------------------------------    # Nav2    # ---------------------------------------------------------    nav2_launch = IncludeLaunchDescription(        PythonLaunchDescriptionSource(            os.path.join(                tb3_nav_dir,                'launch',                'navigation2.launch.py'            )        ),        launch_arguments={            'map': map_file,            'use_sim_time': 'true',            'params_file': params_file,        }.items(),    )    # ---------------------------------------------------------    # Launch everything    # ---------------------------------------------------------    return LaunchDescription([        world_arg,        map_arg,        x_pose_arg,        y_pose_arg,        world_launch,        nav2_launch,    ])